mapper.update:
update transfer_record
transfer_no = #{transferNo}, from_account_id = #{fromAccountId}, to_account_id = #{toAccountId}, from_user_id = #{fromUserId}, to_user_id = #{toUserId}, amount = #{amount}, fee = #{fee}, status = #{status}, fail_reason = #{failReason}, create_time = #{createTime}, update_time = #{updateTime},
where id = #{id}

UPDATE bank_account
SET balance = balance - #{amount},
    available_balance = available_balance - #{amount}
WHERE card_number = #{accountId}
  AND available_balance >= #{amount}

UPDATE bank_account
SET balance = balance + #{amount},
    available_balance = available_balance + #{amount}
WHERE card_number = #{accountId}

UPDATE bank_account
SET
    frozen_balance = frozen_balance - #{amount},
    available_balance = available_balance + #{amount}
WHERE card_number = #{toAccountId}
  AND frozen_balance >= #{amount}
